sys_script_include.script:
var DecisionV2Utils = Class.create();
DecisionV2Utils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
	//カスタムDecisionテーブルの情報を参照
    getDecisionResults:function() {
    var dtAPI = new sn_dt.DecisionTableAPI();
    var params = JSON.parse(this.getParameter("inputs"));
    var inputs = {
        u_id: '' +params.u_id

    };

    var dtSysId = "fe3fc51d0f1b3a147409c9c530d1b215"; //カスタムDecisionテーブルのsys_id
    var response = dtAPI.getDecision(dtSysId, inputs);
    //var response = dtAPI.getAnswers(dtSysId);
	//var response = dtAPI.getAll();
	gs.info("input" + JSON.stringify(inputs));
	gs.info("response" + JSON.stringify(response));
	return JSON.stringify(response);
	/*var output ={};
	if(response && response.result_elements) {
		output.u_pattenrn_1 = response.result_elements.u_pattenrn_1;
		output.step2_1 = response.result_elements.step2_1;
	} else {
        output.message ='結策表に一致するルールが存在しません';
	}
    return JSON.stringify(output);*/
	},

    getRoleResult:function() {
    var gr = new GlideRecord('x_846092_decisio_0_customize_decision');
    gr.addQuery('u_id', 'Decisionで承認者を設定_v3');
    gr.addQuery('u_effective_start', "<=", "javascript:gs.endOfToday()");
    gr.query();

 var results = [];
        while (gr.next()) {
            results.push({
                u_id: gr.getValue('u_id'),
                u_result_step2_1: gr.getValue('u_result_step2_1'),
                u_pattenrn_1: gr.getValue('u_pattenrn_1')
            });
        }
gs.info('results' + results);
        return results; 
    },





    type: 'DecisionV2Utils'
});
